const menu=document.getElementById('nav');
const menuBtn=document.getElementById('menuBtn');
let active='All';

const money=n=>`₹${Number(n).toLocaleString('en-IN')}`;
const cats=['All',...new Set(PRODUCTS.map(p=>p.category))];
filters.innerHTML=cats.map(c=>`<button class="filter ${c==='All'?'active':''}" data-cat="${c}">${c}</button>`).join('');
filters.querySelectorAll('.filter').forEach(b=>b.onclick=()=>{active=b.dataset.cat;filters.querySelectorAll('.filter').forEach(x=>x.classList.toggle('active',x===b));render();});
search.addEventListener('input',render);
menuBtn.addEventListener('click',()=>menu.classList.toggle('open'));
menu.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>menu.classList.remove('open')));

defaultCrop=(p)=>p.crop||[0,0,917,1728];
function drawCrop(canvas,p){
  const ctx=canvas.getContext('2d'); const img=new Image();
  img.onload=()=>{
    const [x,y,w,h]=defaultCrop(p); const ar=canvas.clientWidth/canvas.clientHeight||1;
    const srcAr=w/h; let sx=x,sy=y,sw=w,sh=h;
    if(srcAr>ar){const nw=h*ar;sx=x+(w-nw)/2;sw=nw}else{const nh=w/ar;sy=y+(h-nh)/2;sh=nh}
    canvas.width=900;canvas.height=620;ctx.clearRect(0,0,900,620);
    ctx.fillStyle='#f6f7f9';ctx.fillRect(0,0,900,620);
    const scale=Math.min(900/sw,620/sh); const dw=sw*scale,dh=sh*scale;
    ctx.drawImage(img,sx,sy,sw,sh,(900-dw)/2,(620-dh)/2,dw,dh);
  }; img.src=PAGE_IMAGES[String(p.page)];
}
function card(p,i){return `<article class="product-card"><div class="photo-wrap"><canvas id="cv-${i}" aria-label="${p.name}"></canvas></div><div class="product-info"><div class="category">${p.category}</div><h3>${p.name}</h3><div class="size">${p.size}</div><div class="price-row"><span class="price">${money(p.price)}</span><span class="source">${p.source}</span></div><button class="order" data-name="${encodeURIComponent(p.name)}">Add to Pick</button></div></article>`}
function render(){
 const q=search.value.trim().toLowerCase();
 const list=PRODUCTS.filter(p=>(active==='All'||p.category===active)&&(!q||`${p.name} ${p.category} ${p.size}`.toLowerCase().includes(q)));
 count.textContent=PRODUCTS.length; empty.hidden=list.length>0;
 grid.innerHTML=list.map((p,i)=>card(p,i)).join('');
 list.forEach((p,i)=>drawCrop(document.getElementById(`cv-${i}`),p));
 grid.querySelectorAll('.order').forEach(b=>b.onclick=()=>openOrder(decodeURIComponent(b.dataset.name)));
}
function openOrder(name){document.getElementById('modalTitle').textContent=name;document.getElementById('modal').classList.add('show')}
document.getElementById('closeModal').onclick=()=>document.getElementById('modal').classList.remove('show');
document.getElementById('modal').onclick=e=>{if(e.target.id==='modal')document.getElementById('modal').classList.remove('show')};
document.getElementById('year').textContent=new Date().getFullYear();
render();
